SELECT acm_id, main_img, acm_name, acm_type, admin_phone_number, address
FROM (
    SELECT a.*, ROWNUM rnum
    FROM (
        SELECT a.acm_id, a.main_img, a.acm_name, t.acm_type, a.admin_phone_number, a.address
        FROM ACCOMMODATION a
        JOIN ACCOMMODATION_TYPE t ON a.acm_type_id = t.acm_type_id

        	a.dlt_flag = 'N'
        	AND a.admin_id = #{admin_id}

                AND INSTR(a.acm_name, #{acm_name}) > 0


                AND a.acm_type_id = #{acm_type_id}


        ORDER BY a.acm_id DESC
    ) a
    WHERE ROWNUM <= #{endRow}
)
WHERE rnum >= #{startRow}

